{"HelperA.dfy": "if |s| == 0 {
  A.Empty(s);
  assert s + t == t;
  A.Empty(s);
} else {
  A.Observe(s);
  var s' := s[1..];
  assert s == [s[0]] + s';
  assert s + t == [s[0]] + (s' + t);
  Prove(s', t);
  A.Observe([s[0]] + (s' + t));
  assert ([s[0]] + (s' + t))[1..] == s' + t;
  assert K.Rev([s[0]] + (s' + t)) == K.Rev(s' + t) + [s[0]];
  assert K.Rev(s' + t) == K.Rev(t) + K.Rev(s');
  assert K.Rev(s + t) == K.Rev(t) + K.Rev(s') + [s[0]];
  assert K.Rev(s) == K.Rev(s') + [s[0]];
}"}

